/**
 * Basit i18n katmanı (UI + maç anlatımı + sözlük: TR/EN/DE/FR/ES/IT/RU/PT/ZH tam). Dil tercihi bir cookie'de tutulur →
 * sunucu bileşenleri istekte doğru dilde render eder. `t(locale, key)` saf fonksiyondur (sözlük
 * bundle'da) → hem sunucu hem istemci bileşenlerinde kullanılabilir.
 *
 * NOT: Maç anlatımı (`src/engine/combat`, `src/server/careerService.ts`) ve motorun ürettiği bazı
 * sabit etiketler (`src/engine/skill/skills.ts` vb.) bu sözlükten geçmez, ayrı bir konudur.
 *
 * Bu modül istemci-güvenlidir (next/headers YOK) → client bileşenleri de `t`/tipleri import edebilir.
 * Sunucu tarafı dil okuma `./server` içindedir.
 */
export type Locale = "tr" | "en" | "de" | "es" | "fr" | "it" | "ru" | "pt" | "zh";
export const LOCALES: Locale[] = ["tr", "en", "de", "es", "fr", "it", "ru", "pt", "zh"];
export const LOCALE_COOKIE = "engarde_locale";
